И еще более сложный пример:



```rust

use std::sync::{Mutex, Arc};
use std::thread;
use std::time::Duration;
use std::collections::HashMap;

struct Bank {

    accounts: Mutex<HashMap<u32, f64>>  // банковские счета
}

impl Bank {
    // функция-конструктор
    fn new() -> Self {
        Bank {
            accounts: Mutex::new(HashMap::new()),
        }
    }
    // добавление денег на счет
    fn deposit(&self, account_id: u32, amount: f64) {

        let mut accounts = self.accounts.lock().unwrap();
        let balance = accounts.entry(account_id).or_insert(0.0);
        *balance += amount;
    }
    // снятие денег со счета
    fn withdraw(&self, account_id: u32, amount: f64) {

        let mut accounts = self.accounts.lock().unwrap();
        let balance = accounts.entry(account_id).or_insert(0.0);
        if *balance >= amount {
            *balance -= amount;
        } 
        else {

            println!("Недостаточно денег на счете: {}", account_id);
        }
    }
    // проверка баланса
    fn check_balance(&self, account_id: u32) -> f64 {

        let accounts = self.accounts.lock().unwrap();
        *accounts.get(&account_id).unwrap_or(&0.0)
    }
}

fn main() {

    let bank = Arc::new(Bank::new());   // банк
    let mut threads = vec![];

    for id in 1..4 {

        let bank_clone = Arc::clone(&bank);
        // создаем поток клиента банка
        let account_thread = thread::spawn(move || {

            // чтобы данные для счетов различались, умножаем на номер счета
            bank_clone.deposit(id, 30.0 * id as f64);
            thread::sleep(Duration::from_millis(200)); // имитация долгой работы
            bank_clone.withdraw(id, 10.0 * id as f64);
            let balance = bank_clone.check_balance(id);
            println!("Счет {} - Остаток на счете: {:.2}", id, balance);
        });

        threads.push(account_thread);
    }

    // ожидаем завершения потоков
    for t in threads {

        t.join().unwrap();
    }
}
```



Здесь определена структура Bank, которая представляет банк и которая содержит объект `Mutex >` для хранения банковских счетов. Каждый счет представлен записью в HashMap, где ключи - представляют числовые номера счетов, а значения типа f64 - количество денег на счете. Несколько потоков имитируют банковские транзакции, включая добавление на счет, снятие средств и проверки баланса. Мьютекс гарантирует, что только один поток может одновременно получить доступ к банковским счетам, предотвращая гонки данных и обеспечивая согласованность данных. Консольный вывод программы:



```bash

Счет 3 - Остаток на счете: 60.00
Счет 2 - Остаток на счете: 40.00
Счет 1 - Остаток на счете: 20.00
```



### Задача производитель-потребитель



Мьютексы нередко используются в многопоточных сценариях производитель-потребитель для синхронизации доступа к общему буферу. Пример демонстрации шаблона производитель-потребитель на основе Mutex:



```rust

use std::sync::{Arc, Mutex};
use std::thread;

const BUFFER_SIZE: usize = 4; // количество производимых элементов одним производителем

fn main() {

    let buffer = Arc::new(Mutex::new(Vec::new())); // общие данные

    let mut threads = vec![];

    // Потоки производителей
    for i in 1..3 {

        // копируем Arc
        let buffer_clone = Arc::clone(&buffer);
        // запускаем поток
        let producer = thread::spawn(move || {

            for j in 0..BUFFER_SIZE {

                let mut buffer = buffer_clone.lock().unwrap();
                let value = i * BUFFER_SIZE + j;
                println!("Producer{} produced {}", i, value);
                buffer.push(value); // добавляем данные в вектор
            }
        });
        threads.push(producer);
    }

    // потоки потребителей
    for i in 1..3 {

        let buffer_clone = Arc::clone(&buffer);
        let consumer = thread::spawn(move || {

            for _ in 0..BUFFER_SIZE {

                let mut buffer = buffer_clone.lock().unwrap(); // получаем данные из буфера
                if let Some(value) = buffer.pop() { // если в буфере есть данные
                    println!("Consumer{} consumed {}", i, value); // потребляем их
                }
            }
        });
        threads.push(consumer);
    }

    for t in threads { t.join().unwrap(); }
}
```



В этом примере несколько потоков-производителей добавляют элементы в общий буфер, а потоки-потребители удаляют и потребляют элементы из одного и того же буфера. Мьютекс обеспечивает монопольный доступ к буферу, предотвращая гонки данных. Консольный вывод:



```bash

Producer2 produced 8
Producer2 produced 9
Producer2 produced 10
Producer2 produced 11
Consumer1 consumed 11
Consumer1 consumed 10
Consumer1 consumed 9
Consumer1 consumed 8
Producer1 produced 4
Producer1 produced 5
Producer1 produced 6
Producer1 produced 7
Consumer2 consumed 7
Consumer2 consumed 6
Consumer2 consumed 5
Consumer2 consumed 4
```

Взаимные блокировки возникают, когда потоки бесконечно ждут друг друга, чтобы снять блокировки мьютекса, что приводит к остановке. Избежание взаимоблокировок имеет важное значение в многопоточном программировании.

![взаимоблокировки ресурсов в rust](/uploads/course-lectures/dfe66d1e26d85c30e016543c0137d0e07883e3ec.png)

Рассмотрим следующий пример, который демонстрирует потенциальную взаимоблокировку

```rust
use std::sync::{Mutex, Arc};
use std::thread;
use std::time::Duration;

fn main() {

    let data1 = Arc::new(Mutex::new(0)); // определяем первый общий ресурс
    let data2 = Arc::new(Mutex::new(0)); // определяем второй общий ресурс

    // создаем 1-й поток
    let thread1 = thread::spawn({
        // копируем оба ресурса
        let data1_clone = Arc::clone(&data1);
        let data2_clone = Arc::clone(&data2);
        move || {

            let mut guard1 = data1_clone.lock().unwrap(); // получаем блокировку на 1-й ресурс
            *guard1 += 1;
            thread::sleep(Duration::from_millis(200));
            let mut guard2 = data2_clone.lock().unwrap(); // получаем блокировку на 2-й ресурс
            *guard2 += 1;
        }
    });

    // создаем 2-й поток
    let thread2 = thread::spawn({

        // копируем оба ресурса
        let data1_clone = Arc::clone(&data1);
        let data2_clone = Arc::clone(&data2);

        move || {
            let mut guard2 = data2_clone.lock().unwrap(); // получаем блокировку на 2-й ресурс
            *guard2 += 1;
            thread::sleep(Duration::from_millis(200));
            let mut guard1 = data1_clone.lock().unwrap(); // получаем блокировку на 1-й ресурс
            *guard1 += 1;
        }
    });
    thread1.join().unwrap();
    thread2.join().unwrap();

    println!("data1 = {}, data2 = {}",
        data1.lock().unwrap(),
        data2.lock().unwrap()
    );
}
```

Здесь в фукции main определяется два ресурса. И также создается два потока. Первый поток сначала блокирует первый ресурс, изменяет его и после небольшой задержки пытается блокировать второй ресурс. Второй поток, наборот, сначала блокирует второй ресурс, изменяет его и потом пытается блокировать первый ресурс. С высокой вероятностью пока первый поток будет ждать разблокировки второго ресурса, первый поток будет ждать разблокировки первого ресурса. В итоге взаимное ожидание приведет к блокировке работы программы.

Чтобы выйти из этой ситуации для получения блокировки мы можем использовать метод **try_lock()** - если с его помощью невозможно получить блокировку, то поток продолжает работу без блокировки. Это может помочь предотвратить взаимоблокировки в ситуациях, когда получение блокировки не является критическим. Например, перепишем предыдущий пример с помощью **try_lock()**:

```rust
use std::sync::{Mutex, Arc};
use std::thread;
use std::time::Duration;

fn check_mutex_and_increase(data_clone: Arc<Mutex<i32>>){
    let mut guard = data_clone.try_lock();
    match guard {
        Ok(ref mut value) => { **value += 1; }
        Err(_) => { println!("Failed to acquire lock, continuing…"); }
    }
}
fn main() {

    let data1 = Arc::new(Mutex::new(0)); // определяем первый общий ресурс
    let data2 = Arc::new(Mutex::new(0)); // определяем второй общий ресурс

    // создаем 1-й поток
    let thread1 = thread::spawn({
        // копируем оба ресурса
        let data1_clone = Arc::clone(&data1);
        let data2_clone = Arc::clone(&data2);
        move || {

            let mut guard1 = data1_clone.lock().unwrap(); // получаем блокировку на 1-й ресурс
            *guard1 += 1;
            thread::sleep(Duration::from_millis(200));
            // получаем блокировку на 2-й ресурс
            check_mutex_and_increase(data2_clone);
        }
    });

    // создаем 2-й поток
    let thread2 = thread::spawn({

        // копируем оба ресурса
        let data1_clone = Arc::clone(&data1);
        let data2_clone = Arc::clone(&data2);

        move || {
            // получаем блокировку на 2-й ресурс
            let mut guard2 = data2_clone.lock().unwrap(); // получаем блокировку на 1-й ресурс
            *guard2 += 1;
            thread::sleep(Duration::from_millis(200));
             // получаем блокировку на 1-й ресурс
            check_mutex_and_increase(data1_clone);
        }
    });
    thread1.join().unwrap();
    thread2.join().unwrap();


    println!("data1 = {}, data2 = {}",
        data1.lock().unwrap(),
        data2.lock().unwrap()
    );
}
```

Здесь также первую блокировку потоки получают с помощью метода `lock()`. Код получения второй блокировки я вынес в отдельную функцию:

```rust
fn check_mutex_and_increase(data_clone: Arc<Mutex<i32>>){
    let mut guard = data_clone.try_lock();
    match guard {
        Ok(ref mut value) => { **value += 1; }
        Err(_) => { println!("Failed to acquire lock, continuing…"); }
    }
}
```

Здесь сначала с помощью вызова `data_clone.try_lock()` пытаемся получить блокировку (метод возвращает объект Result). Далее с помощью `match` проверяем полученный результат. Если ошибки нет, то в value мы получаем мьютекс и через него обращаемся к самому значению, увеличивая его на 1. Обратите внимание на двойное разыменование - `**value`

Если же произошла ошибка, то есть блокировку невозможно получить, то просто выводим соответствующее сообщение.

Два потока также пытаются получить блокировку для двух одних и тех же ресурсов:

```rust
let mut guard1 = data1_clone.lock().unwrap(); // получаем блокировку на 1-й ресурс
*guard1 += 1;
thread::sleep(Duration::from_millis(200));
check_mutex_and_increase(data2_clone);
```

В итоге опять же первые ресурсы будут успешно заблокированы потоками, а при получение вторых ресурсов может возникнуть ошибка. Соответственно мы получим следующий консольный вывод:

```rust
Failed to acquire lock, continuing…
Failed to acquire lock, continuing…
data1 = 1, data2 = 1
```

**RwLock** (Read-Write Lock или блокировка чтения-записи) применяется в многопоточном программировании на Rust, позволяя нескольким потокам одновременно читать данные, и только один поток при этом имеет монопольный доступ для записи. Данный инструмент полезен для сценариев с различными требованиями к чтению и записи.



Наглядная схема действия **RwLock**:



![указатель rwlock в rust](/uploads/course-lectures/2e5affd0ba8901d48ec73fc4b6e7bc66aa669e10.png)



Для получения монопольной блокировки на запись у RwLock применяется метод **write()**, а для чтения значения - метод **read()**



Рассмотрим простейший пример:



```rust

use std::sync::{Arc, RwLock};
use std::thread;
use std::time::Duration;

fn write(data: Arc<RwLock<i32>>) {

    // устанавливаем блокировку на запись
    let mut data_lock = data.write().unwrap();
    for pass in 1..4 {
        *data_lock += 1;        // изменяем значение
        println!("Writer (Pass{}) - value: {}", pass, *data_lock);
        thread::sleep(Duration::from_millis(400)); // имитация долгой работы
    }
}

fn read(id: u32, data: Arc<RwLock<i32>>) {
    // получаем значение для чтения
    let value = data.read().unwrap();
    for pass in 1..4 {
        println!("Reader {} (Pass{}) - value: {}", id, pass, value);
        thread::sleep(Duration::from_millis(200)); // имитация долгой работы
    }
}

fn main() {

    let value = Arc::new(RwLock::new(0));   // определяем объект RwLock
    let mut threads = vec![];

    let value_copy = Arc::clone(&value);
    // создаем поток писателя
    let writer = thread::spawn(move || write(value_copy));
    threads.push(writer);

    for id in 1..4 {

        let value_copy = Arc::clone(&value);
        // создаем поток читателя
        let reader = thread::spawn(move || read(id, value_copy));

        threads.push(reader);
    }

    // ожидаем завершения потоков
    for t in threads {

        t.join().unwrap();
    }
}
```



Здесь в функции main сначала создаем собственно объект RwLock, который обернут в Arc:



```rust
let value = Arc::new(RwLock::new(0));   // определяем объект RwLock
```



Для создания объекта RwLock применяется метод-конструктор `RwLock::new()`, в который передается собственно то значение, доступом к которому будет управлять RwLock. В нашем случае это число 0.



Вектор threads будет содержать все запускаемые потоки:



```rust
let mut threads = vec![];
```



Далее создаем поток условного "писателя". Он будет выполнять функцию write(), в которую передается копия объекта Arc.



```rust

let value_copy = Arc::clone(&value);
// создаем поток писателя
let writer = thread::spawn(move || write(value_copy));
```



В этой функции write сначала с помощью метода `write()` устанавливаем блокировку на запись и в цикле четыре раза последовательно изменяем значение, прибавляя к нему 1:



```rust

fn write(data: Arc<RwLock<i32>>) {

    let mut data_lock = data.write().unwrap();
    for pass in 1..4 {
        *data_lock += 1;
        println!("Writer (Pass{}) - value: {}", pass, *data_lock);
        thread::sleep(Duration::from_millis(400)); // имитация долгой работы
    }
}
```



Для имитации долгой работы устанавливается задержка в 400 миллисекунд. И для наглядности выводим текущее значение на консоль. При завершении области действия блокировки - в данном случае при завершении функции блокировка на запись автоматически удаляется.



Далее в функции main создаем три потока на чтение:



```rust

 for id in 1..4 {

    let value_copy = Arc::clone(&value);
    // создаем поток читателя
    let reader = thread::spawn(move || read(id, value_copy));

    threads.push(reader);
}
```



При запуске потока читателя запускается функция read, в которую передаем номер читателя и копию объекта Arc. В функции read() получаем значение из RwLock и выводим его на консоль:



```rust

fn read(id: u32, data: Arc<RwLock<i32>>) {
    // получаем значение для чтения
    let value = data.read().unwrap();
    for pass in 1..4 {
        println!("Reader {} (Pass{}) - value: {}", id, pass, value);
        thread::sleep(Duration::from_millis(200)); // имитация долгой работы
    }
}
```



Опять же для наглядности устанавливаем небольшую задержку в 200 миллисекунд (меньше чем у писателя). Стоит отметить, что при чтении никакой блокировки не происходит.



Запустим приложение и проинспектируем результат:



```bash

